// --- COST MATH START ---
// USD per 1,000,000 tokens. These are DEFAULTS, not gospel: check every number
// against your provider's current price list before you trust the cap.
var DEFAULT_COST_TABLE = {
  'gpt-4o': { input: 2.5, output: 10.0 },
  'gpt-4o-mini': { input: 0.15, output: 0.6 },
  'claude-haiku': { input: 0.8, output: 4.0 },
  'claude-sonnet': { input: 3.0, output: 15.0 },
  'claude-opus': { input: 15.0, output: 75.0 },
  'default': { input: 5.0, output: 15.0 }
};

function resolveModelRate(model, table) {
  var t = table || DEFAULT_COST_TABLE;
  var key = String(model === undefined || model === null ? '' : model).toLowerCase().trim();
  if (Object.prototype.hasOwnProperty.call(t, key)) { return t[key]; }
  var names = Object.keys(t);
  var best = null;
  for (var i = 0; i < names.length; i++) {
    var n = names[i];
    if (n === 'default') { continue; }
    if (key.indexOf(n) === 0) {
      if (best === null || n.length > best.length) { best = n; }
    }
  }
  if (best !== null) { return t[best]; }
  if (Object.prototype.hasOwnProperty.call(t, 'default')) { return t['default']; }
  return DEFAULT_COST_TABLE['default'];
}

function estimateCostUsd(model, inputTokens, outputTokens, table) {
  var rate = resolveModelRate(model, table);
  var inTok = Number(inputTokens);
  var outTok = Number(outputTokens);
  if (!isFinite(inTok)) { inTok = 0; }
  if (!isFinite(outTok)) { outTok = 0; }
  if (inTok < 0 || outTok < 0) { throw new Error('token counts must be >= 0'); }
  var cost = (inTok / 1000000) * Number(rate.input) + (outTok / 1000000) * Number(rate.output);
  return Math.round(cost * 1000000) / 1000000;
}
// --- COST MATH END ---

function envStr(name, fallback) {
  try {
    var v = $env[name];
    if (v === undefined || v === null || v === '') { return fallback; }
    return String(v);
  } catch (e) {
    return fallback;
  }
}
function pick(v, envName, fallback) {
  if (v !== undefined && v !== null && v !== '') { return v; }
  return envStr(envName, fallback);
}

var out = [];
var items = $input.all();
for (var idx = 0; idx < items.length; idx++) {
  var j = items[idx].json || {};
  var table = j.cost_table || DEFAULT_COST_TABLE;
  var cost = estimateCostUsd(j.model, j.input_tokens, j.output_tokens, table);
  out.push({ json: {
    workflow_key: String(pick(j.workflow_key, 'N8N_CB_WORKFLOW_KEY', 'default')),
    spend_window: String(pick(j.spend_window, 'N8N_CB_SPEND_WINDOW', 'day')),
    model: String(j.model === undefined || j.model === null ? 'unknown' : j.model),
    input_tokens: Number(j.input_tokens) || 0,
    output_tokens: Number(j.output_tokens) || 0,
    call_cost_usd: cost,
    cap_usd: Number(pick(j.cap_usd, 'N8N_CB_SPEND_CAP_USD', '5'))
  } });
}
return out;

var cfg = $('Price The Call').first().json;
var row = $input.first().json || {};
var cap = Number(cfg.cap_usd);
var total = Number(row.cost_usd || 0);
var over = total >= cap;
return [{ json: {
  workflow_key: cfg.workflow_key,
  spend_window: cfg.spend_window,
  window_start: row.window_start || null,
  window_total_usd: total,
  call_count: Number(row.call_count || 0),
  last_call_usd: Number(cfg.call_cost_usd || 0),
  cap_usd: cap,
  remaining_usd: Math.round((cap - total) * 1000000) / 1000000,
  over_cap: over,
  reason: over
    ? ('spend cap exceeded: ' + total + ' USD of ' + cap + ' USD in the current ' + cfg.spend_window)
    : 'within spend cap'
} }];

// Build one alert payload. Wire the NEXT node to Slack / email / PagerDuty.
var j = $input.first().json || {};
return [{ json: {
  alert: true,
  severity: 'critical',
  module: 'spend-cap',
  workflow_key: j.workflow_key || 'unknown',
  reason: j.reason || 'limit exceeded',
  detail: j,
  execution_id: $execution.id,
  fired_at: new Date().toISOString()
} }];
